var configurações','%d hidden'=>'%d ocultos','Toggle all'=>'Alternar todos','GenerateBlocks Pro is active. This core block is hidden from the inserter automatically because GenerateBlocks Pro provides an extended variant. If GenerateBlocks Pro is deactivated, the core block reappears automatically.'=>'O GenerateBlocks Pro está ativo. Este bloco principal é ocultado automaticamente do insersor porque o GenerateBlocks Pro oferece uma variante estendida. Se o GenerateBlocks Pro for desativado, o bloco principal reaparece automaticamente.','Pro variant active'=>'Variante Pro ativa','protected'=>'protegido','Save'=>'Salvar','Embed variations'=>'Variações de incorporação','Variations of the "Embed" block (YouTube, Reddit, Vimeo, …). Checked variations are removed in the editor; the base "Embed" block remains available.'=>'Variações do bloco "Incorporar" (YouTube, Reddit, Vimeo, …). As variações marcadas são removidas do editor; o bloco base "Incorporar" continua disponível.','Uncategorized'=>'Sem categoria','Settings'=>'Configurações']];